import docx
d=docx.Document('output/offer_letter_filled.docx')
def walk(t,p=''):
    for para in t.paragraphs:
        if para.text.strip(): print(p+para.text)
    for tbl in t.tables:
        for row in tbl.rows:
            for c in row.cells:
                walk(c,p+'  ')
walk(d)
for s in d.sections:
    for hf in (s.header,s.first_page_header,s.even_page_header,s.footer,s.first_page_footer,s.even_page_footer):
        for para in hf.paragraphs:
            if para.text.strip(): print('[HF]',para.text)
print('--- marker scan ---')
import re
txt=' '.join(p.text for p in d.paragraphs)
print('leftover {{ }}:', bool(re.search(r'{{|}}', txt)))
print('RELOCATION mentions present?:', 'RELOCATION' in txt, '| relocation word:', 'elocation' in txt.lower())
"
